const HARNESS_PLAN = [
  { k: '1 · Freeze the sources', v: 'Ingest the token tables, the lexicon subset and the reference editions once, under content commitments the MCP refuses to re-ingest if the upstream revision moved. A benchmark against a moving source is not a benchmark.', meta: 'ingest-sources.mts · /admin/segments refuses a moved revision' },
  { k: '2 · Pre-register the sets', v: 'A dev set (55 cases) to tune on, a regression set (580 planted errors, six kinds) that measures the checker and is never pooled with a capability set, and a held-out set written ONCE and locked. A set says task: translate; a localise arm on it is refused.', meta: 'suiteKind: capability | regression · held-out: locked' },
  { k: '3 · Set the floor and the ceiling', v: 'control-web runs the WEB through the checker as the ceiling (its chrF against itself excluded). gloss renders the tables\' glosses in gloss order with one alignment per token — the floor, and pure, so the regression suite can plant its errors in the same text and know exactly what it planted.', meta: 'arms: control-web · gloss · model-src · model-lex · model-mem' },
  { k: '4 · Run the deterministic graders first', v: 'scope, fidelity-checks (the same four checks the plan runs), source-coverage, perturbation-catch, chrF per reference edition. A judge grader (fidelity) sees the WEB as a flagged reference, and reads cantTell — out of the agent\'s denominator — when its key is absent. A run with no verdict carries a failureCause: agent, grader or environment; only agent counts against the agent.', meta: 'ALL_GRADERS — one list; the one-run path once had its own' },
  { k: '5 · Read the floor and the ceiling before reading the model', v: 'If the checker blocks the WEB, the checker is wrong, not the WEB. Tune on dev until both read ~0.99; re-run regression to see what the tuning cost in catch rate; then — and only then — run the model arms, and quote held-out alone.', meta: 'tr-dev-local-2 → -3 · tr-regression-local-3' },
  { k: '6 · Pilot, then drive', v: 'A whole-Bible driver walks the source chapter by chapter in chunks of eight verses with a ledger and a resume; a pilot over small books (Jonah, Ruth, Philemon, Jude, Obadiah, 2–3 John: 231 verses) set the revise pass, the text prompts, prompt caching and the D1 bind limit before a dollar went on a long book. Then one chapter: John 3.', meta: 'translate-bible.mts --chapters John.3' },
  { k: '7 · Publish under an issuer', v: 'Export picks one proposal per verse (approved > not rejected > fewer blocking > later), from driver runs only; a service agent chartered by the scripture steward signs every verse descriptor with a key it holds only as a delegate. The edition carries no Berean name.', meta: 'rbs-bible.svc · AKCS content-signer key · ERC-7710 leaf' },
];

const FOUND = [
  { k: 'The checker blocked the Bible', v: 'First dev run: 67% of the WEB (the ceiling) and 80% of the floor failed a blocking check. Five rules were wrong, not the texts: curly apostrophes (don’t ≠ don\'t); one `not` demanded per negator where English distributes one over “or” and οὐ μή is one negation; numbers that did not compose (“fourteenth” is 4 + 10, “three hundred” 3 × 100); divine-name claims by a Strong\'s that is also a common noun (πνεῦμα in “poor in spirit”, עֶלְיוֹן “upper pool”); “dropped content tokens” that were conjunctions and prepositions English absorbs.', meta: 'fidelity-checks: control-web 0.99 · gloss 0.99 after · blocking rate 0.09 / 0.24' },
  { k: 'The regression suite priced the fix', v: 'Freeing pronoun drops raised catch 0.90 → 0.94 overall (added-clause 0.76 → 0.99, dropped-clause 0.92 → 0.97) and cost changed-name 1.00 → 0.91 and swapped-speaker 0.99 → 0.90. The suite exists so that a rule loosened for the ceiling shows what it stopped catching.', meta: 'tr-regression-local-3 · 580 runs · per kind, never pooled' },
  { k: 'The pilot changed the plan', v: 'Jonah: 1 of 6 chunks clean on a single draft; 6 of 6 with a guarded revise pass that hands the model its draft and the failing checks. Prefixed waw read as a dropped token until `Conj-w | V-…` was parsed as the verb it is; נָא and לֵאמֹר-as-infinitive became free; numeral runs compose under + and × in any bracketing; a hyphenated compound reads as its parts. Jude\'s sentences carried more Strong\'s numbers than D1 allows binds, so every IN (…) is paged.', meta: '5 lessons in the driver\'s record; each a test' },
  { k: 'John 3 found two more', v: 'Two chunks still blocked after revise. 3:4 — δεύτερον is glossed “secondly”, so “a second time” read as a number the source did not have; the quantities check now reads an ordinal adverb as its number. 3:13 — εἰ μή is exceptive, and the negation check wanted a `not` for a μή the draft had rightly rendered “except”; a negator after εἰ / ἐάν rendered except / unless is carried. Both drafts were right; both rules were wrong; both are tests; the chapter re-ran to 36 of 36.', meta: 'John.3.1-8 blocking 2 → 0 · John.3.9-16 blocking 1 → 0 · $0.77' },
  { k: 'The prompt got cheaper without getting shorter', v: 'JSON out of the model\'s context (the tools render a `prompt` line per item): 30k → 19k input tokens a chunk. The system and the passage prefix marked ephemeral for caching; the revision reads the draft\'s prefix from cache — once the tool description was made identical across the two calls (tools precede the system in the cache key). Cache reads and writes are on the usage line of every record.', meta: '$0.012–0.023 a verse on Claude Sonnet 5 · whole Bible ≈ $650' },
];


const LAYERS = [
  { k: 'DOLCE + DnS', v: 'The upper distinction the whole design rests on: a DESCRIPTION (a norm, a brief, a plan — what should hold) against a SITUATION (what a run claims did hold). A translation brief is a dul:Norm; a run is an at:Situation that satisfies or fails it. Without this split a policy and an outcome are the same kind of thing and nothing can be measured against anything.', meta: 'dul: · ontology/upper/dolce.ttl (generated subset, 37 classes, 74 axioms)' },
  { k: 'PROV-O', v: 'Every step of a run is a prov:Activity, every input and output a prov:Entity, every model and tool a prov:Agent. The run record the orchestration writes IS a PROV document, so "which model, which prompt version, which tool outputs, which checks" is a graph query, not a log search.', meta: 'prov: · RunRecorder emits prov:Activity / prov:Entity / wasDerivedFrom' },
  { k: 'P-Plan + EP-Plan', v: 'A plan is a p-plan:Plan of p-plan:Steps with Variables; EP-Plan adds Constraints and Objectives a step must satisfy. This is where "the drafter never sees English" stops being a sentence in a brief and becomes a typed constraint on the inputs of one step — checkable before a run and auditable after it.', meta: 'p-plan: ep-plan: · btr:TranslationPlan ⊑ at:Plan ⊑ p-plan:Plan (declared; the TypeScript plan is validated against it)' },
  { k: 'agentic-trust (at:)', v: 'The substrate\'s own base: Agent, Capability, Skill, Archetype, Plan, Observation, AssessmentResult, Category, ContentCommitment. A skill REALIZES a capability; a capability has a dotted id the registry keys on; an archetype is compiled from the skills attached to it. Every translation class reaches one of these — that is what lets the same Lab, the same record checker and the same registry run a translation agent and a grant-writing agent alike.', meta: 'at: · 1.3.0, CHANGELOG, tagged' },
  { k: 'faith · publishing · commerce', v: 'The church today (people groups, bodies), the corpus model (a release carries a snapshot root; a verse text is a content revision with a commitment), and licence-as-offer. Scripture specialises these rather than re-minting them: an edition is a pub:CorpusRelease, an apostolic body is faith\'s ekklesia.', meta: 'gc: fci: pub: cc:' },
  { k: 'scripture (scr:)', v: 'The text as a graph: loci, editions, the narrative (27 kinds of event, the Searle split of speech acts, roles, places, lineages, collectives), attestation ("an entity is never asserted true; it is attested in verses by named sources"), and the knowledge-base classes — key term, concept, divine name, divine person, unit, festival, membership — under one abstract root, scr:Referent.', meta: 'scr: · 1.1.0 · 120+ classes, 24+ shapes, the first R-box' },
  { k: 'the knowledge base (skb:)', v: 'The A-box: 3,129 persons with kinship and period, 1,007 places (870 geocoded), 39 supernatural beings, 50 named things, 5,169 key terms, 50 concepts, 16 divine names on 3 divine persons, 34 units — 177k triples, generated from CC BY scholarship (TIPNR, OpenBible, STEP) plus curated rules, in its own named graph.', meta: 'urn:skills:context:scripture:kb · ontology/scripture.kb/*.ttl' },
  { k: 'the explorer snapshot (skx:)', v: 'A second A-box under its own licence: 477 narrative events with participants, places, years and 56k attesting verses; 78 collectives; 843 memberships with roles; and a 3,000-row crosswalk that puts the explorer\'s canonical id on the knowledge base\'s own referents. Theographic is share-alike, so this graph is kept apart from the CC BY one and the join between them is a cross-reference, not a merge.', meta: 'urn:skills:context:scripture:kb-sa · CC BY-SA 4.0 · built from the explorer\'s database export' },
  { k: 'english-varieties (eng:) → language varieties', v: 'What a target VARIETY is and what a change between two of them is: spelling rules, lexical correspondences by sense, constructions with a permission, punctuation, register, the style profile that binds them. The rules engine\'s JSON is a projection of this file. Being lifted to a language-neutral layer so Arabic is a sibling of English, not a tenant.', meta: 'eng: 1.0.0 · lv: planned (O4a)' },
  { k: 'bible-translation (btr:)', v: 'The translation domain: source and target editions, segments and tokens, alignments, senses and renderings, the brief, runs, checks (with kind, severity, verdict), critique, blind review, benchmark passages, perturbations, arms — and since October 17 the referent resolution and one rendering class over the whole spine. Twenty vocabularies; every enum in the code is a projection of them.', meta: 'btr: 1.1.0 · 55 classes, 36 shapes, 20 vocabularies' },
];

const FOUR_BOXES = [
  { k: 'T-box — the classes', v: 'What kinds of thing exist and how they nest: a scr:DivinePerson is an at:Agent and a scr:Referent and NOT a scr:SupernaturalBeing (a sibling, deliberately — Baal is a being of the narrative; God is not classified beside him). A btr:ReferentResolution is an at:Observation. Preflight refuses a class that reaches no upper anchor, and a class in no semantic cluster, because a class nobody can see is a class nobody uses.', meta: 'owl:Class · rdfs:subClassOf · at:inSemanticCluster' },
  { k: 'R-box — the relations and their logic', v: 'Inverses the loaders materialise (a segment hasTranslation ↔ a translation ofSegment), a transitive ancestor chain over parent, functional fields (one check kind, one severity, one verdict, one brief digest), a property chain (a translation\'s source edition is its segment\'s), and disjointness over editions, record kinds and vocabulary schemes. Reasoned over in preflight with an OWL-RL closure — fourteen competency-question fixtures must hold — and never in the store, which stays inference-off after a corrupt closure once wedged every write.', meta: 'owl:inverseOf · TransitiveProperty · FunctionalProperty · propertyChainAxiom · AllDisjointClasses · scripts/reason_ontology.py' },
  { k: 'C-box — the controlled values', v: 'Twenty closed lists in bible-translation alone: check kinds, severities, verdicts, statuses, genres, difficulty tags, perturbation kinds, arm kinds, task kinds, resolution methods. Each value is `skos:inScheme` + `skos:notation`. They are the SOURCE of every TypeScript union in the harness and the MCP: a literal the code uses that is not a notation fails the build. The day the check was written it found two drifts nobody had noticed.', meta: 'skos:inScheme · skos:notation · scripts/project_vocabularies.py --check' },
  { k: 'A-box — the referents', v: 'The individuals: Aaron, Capernaum, the tribe of Levi, the Holy Spirit, ἀγαπάω, the concept Covenant, the cubit, the event "Jesus walks on water". ONE node each, with its source-language forms, its attestations, its authority cross-references (TIPNR, Theographic, Wikidata, Pleiades), and — per target language — its renderings. The translation is held to these nodes, never to an English spelling.', meta: 'skb: skx: · 238k triples across two graphs' },
];

const DRIVES_SKILL = [
  { k: 'The capability id and the classes a skill covers', v: 'A SKILL.md\'s frontmatter names its capability (btr.translate.draft, btr.referents.resolve — dotted ids the registry keys on), the classes it covers and the classes it excludes. The data graph restates the same capability IRI with the classes the skill PRODUCES and CONSUMES; preflight holds the two to each other. The archetype (the Translation Agent) is COMPILED from the skills attached to it — a definition whose tools have only an id and a description is the sign of a broken join, not of a thin agent.', meta: 'skills/bible-translation/*/SKILL.md · ontology/bible-translation.data.ttl · register-bible-translation.mjs' },
  { k: 'The record section is generated from the shapes', v: 'Every writer skill ends with "The record this run produces": one object per produced class, its required fields, its optional fields, the controlled values allowed — written by a script from the SHACL shape, not by hand. Change the shape, regenerate, and the body changes; a body the ontology has moved past fails preflight. The harness validates the record a run leaves against the SAME shape, so what the skill promises and what the state check demands cannot disagree.', meta: 'scripts/gen_record_sections.py --domain bible-translation · the state check' },
  { k: 'A new skill in an hour', v: 'resolve-referents, written October 17: a class (btr:ReferentResolution), a shape with a required field, a vocabulary (resolution method), a capability row, a producesClass row, the body — and the record section appeared, the registry took the capability, the archetype gained a twelfth tool. The runtime step that calls it is the next piece; the contract it will be held to already exists.', meta: 'skill:bible-translation/resolve-referents · version 1' },
  { k: 'What a skill may not do is in the ontology too', v: 'The brief is a dul:Norm with typed fields (textual-basis policy, gender-language policy, group-name policy, deity-pronoun policy, recall policy, what is shown to and hidden from the drafter) and a digest. The skill text and the data graph state the same fields, so the policy register — the document a theologian reads — is generated from the graph rather than maintained beside it.', meta: 'btr:TranslationBrief · ex:brief-amer-v1 · policy-register.md' },
];

const DRIVES_KB = [
  { k: 'Consistency is bound to the referent', v: '"Judas" names six men; "Joshua" and "Jesus" are one Greek word; "love" is three. A string cannot carry consistency across a Bible. A TIPNR IRI can: the names tool resolves a token AT THIS REFERENCE to skb:person-Judas_Mat.10.4-Act, the rendering is a row on that node, and the names check holds the draft to the node. A new target language adds rows and never adds nodes.', meta: 'btr:NameRendering = referent × variety × text × policy × decision' },
  { k: 'God, the Son, the Holy Spirit are nodes; the names are forms', v: 'Until October 17 the knowledge base had sixteen divine NAME forms with conventions and no referent behind them. Now יהוה, אֱלֹהִים, אֵל, שַׁדַּי, θεός are forms of one node (skb:divine-god); Ἰησοῦς and Χριστός of another, the same node as TIPNR\'s person Jesus; πνεῦμα ἅγιον of a third. κύριος is a form of two and the verse decides. A rendering may be keyed to referent AND form, because יהוה → "the LORD" and אֱלֹהִים → "God" are two renderings of one referent. The Trinity is a concept rule on the three nodes, never a word inserted in the text.', meta: 'scr:DivinePerson · scr:formOf · btr:forNameForm · skb:concept-trinity' },
  { k: 'Every aspect, not a list of kinds', v: 'People, places, collectives, events, speech acts, offices, realia, time, lexemes, concepts, textual variants, pericopes — all kinds of one abstract scr:Referent, all rendered by one mechanism. The guarantee is not the list but a NUMBER: every content token of the frozen source carries a Strong\'s number and every number is a key term (100% lexical coverage by construction); how many reach a decided rendering, a sense or a concept rule above the gloss is measured per book and per semantic domain. John today: 3,067 content tokens — 7.3% referent-rendered, 6.6% referent reached without a rendering yet, 12.2% under a concept rule or convention, 73.9% gloss only. That last number is the backlog, worked per domain before a book is drafted.', meta: 'scripts/referent-coverage-report.py John · 22 semantic domains' },
  { k: 'The explorer is the system of record for events and collectives', v: 'The Bible explorer at explorer.faithnet.io had already reconciled Theographic\'s 450 events, 78 organisations and 843 memberships onto TIPNR and OpenBible — the two sources the knowledge base is built from — and recorded the TIPNR id of each node. So the join exists; it is now a 3,000-row crosswalk of authority cross-references on the knowledge base\'s IRIs, with the explorer\'s own match confidence carried through. One referent, two authority ids; two licences, two graphs, one cross-reference between them.', meta: 'ontology/scripture.kb-sa · explorer.faithnet.io · scripts/build_scripture_explorer_graph.py' },
  { k: 'Evidence, never authority', v: 'The scripture graph\'s own scope note: an entity is never asserted true, it is attested in verses by named sources. Every knowledge-base record carries where it came from (dataset, licence, confidence, method); a generated event, when Theographic has none for a pericope, is proposed by a model, read blind by a second model family, and signed by a person before a drafter or a check may read it.', meta: 'scr:SourceAttestation · scr:AuthorityXref · scr:matchMethod' },
];

const DRIVES_PLAN = [
  { k: 'The plan is declared, not hand-coded', v: 'Today the translate plan is 366 lines of TypeScript and "the drafter never sees English" is a comment, a test and a sentence in the brief. In the ontology it is a btr:TranslationPlan of typed steps with EP-Plan constraints: step `draft` may take no input typed btr:ReferenceEdition or btr:TextSegment of the BSB. The TypeScript plan becomes a PROJECTION validated against the graph — same tools, same inputs, same guards — and the invariant becomes something a grader can read off the run record rather than trust.', meta: 'btr:TranslationPlan ⊑ p-plan:Plan · btr:StepConstraint ⊑ ep-plan:Constraint · scripts/project-plan --check (O4b)' },
  { k: 'Language changes the rows, not the plan', v: 'A second target language changes btr:targetVariety, the brief and the style profile. The plan graph — tokens → lexicon → names → referents → draft → checks → revise → critic → propose — is unchanged, and so are the constraints. That is what "consistent regardless of language" means in practice: the Arabic edition runs the same declared plan against the same referents with different rendering rows.', meta: 'btr:targetVariety · lv:Variety (planned)' },
  { k: 'The referent pass is a step with a record', v: 'Before the draft step, every name, divine name, key term and quotation of a pericope is resolved to its node — method and confidence per token, unresolved tokens listed, never guessed. The drafter is shown the resolutions as text; the names and speaker checks read them; the sheet of a book\'s resolutions is what a reviewer signs. A model-proposed resolution under the brief\'s threshold is "cannot tell" to the checks: out of the denominator, in the reviewer\'s queue, never a silent pass.', meta: 'btr:ReferentResolution · resolve-referents · invariant 10' },
  { k: 'Every step is a PROV activity, so behaviour is gradable', v: 'The run record names each step, its inputs, its outputs and its usage (cache reads and writes included). With the plan graph beside it a grader can ask "did the referent step run before the draft", "did any step input carry an English edition", "did a blocking check lead to a revise", "is the critic a different model family", "does every lexicon fact the draft cites appear in a tool output of this run" — a behaviour suite over the trajectory, kept apart from the capability numbers.', meta: 'p-plan:correspondsToStep · suiteKind: behaviour (H2)' },
];

const DRIVES_HARNESS = [
  { k: 'Graders are keyed to the layer they measure', v: 'A map says which graders move when which skill, knowledge-base file or ontology layer changes: source-coverage and recall-independence for the drafter skill, fidelity-checks for the brief, perturbation-catch for the checker, fidelity-judge for the concept rules. A change to one thing runs the same pre-registered set before and after; the report names the layer. The map itself becomes a projection of the ontology (btr:measuresCapability).', meta: 'evaluations/bible-translation/skill-graders.json · skill-performance-report.mts --diff' },
  { k: 'Perturbation kinds, difficulty tags and arm kinds are C-box values', v: 'The regression suite plants errors of nine kinds; the benchmark stratifies by genre and difficulty; the arms are pre-registered kinds. All three are controlled vocabularies in the ontology, and the code\'s unions are held to them. The suite that measures the checker and the sets that measure the model are never pooled — the vocabulary says which is which (suiteKind: capability | regression | behaviour).', meta: 'btr:PerturbationKind · btr:DifficultyTag · btr:ArmKind · btr:TaskKind' },
  { k: 'Acceptance conditions per case are typed', v: 'The next grader: an expert attaches to a hard passage conditions of a controlled kind — preserve-negation, preserve-agent-patient, retain-ambiguity, no-explanatory-insertion, preserve-referent, render-concept — each saying which checker is competent to judge it: code (compiled to a scoped deterministic grader), judge (a rubric criterion) or human. The number a scholar can read is "38 of 40 difficult passages met every expert condition", not "8/10".', meta: 'btr:AcceptanceCondition ⊑ dul:Norm · btr:conditionKind (H1)' },
  { k: 'The record is what gets graded', v: 'A run leaves typed records (a translation, its alignments, its checks, its referent resolutions) and the state check validates them against the shapes the skill was generated from. An answer with no record is absent, not partially right; a record from a previous run is stale, not a pass. Every number says its set, its version, its arm, its judge model and its denominator; a run with no verdict carries a failure cause, and only the agent\'s own failures count against the agent.', meta: 'outcome-per-class · failureCause: agent | grader | environment · judge tier named' },
  { k: 'The floor and the ceiling come first', v: 'Before any model is measured, the checker is: a public-domain human translation runs through it as the ceiling, the interlinear gloss as the floor. The first dev run blocked 67% of the ceiling — five rules were wrong, not the Bible. After tuning both read 0.99, and the regression suite priced what the tuning cost in catch rate (0.90 → 0.94 overall; two kinds fell). A checker whose precision and recall are unmeasured is an opinion.', meta: 'control-web · gloss · tr-dev-local-3 · tr-regression-local-3' },
  { k: 'The improvement loop closes through the ontology', v: 'A finding (a reviewer\'s verdict, a check failure, a judge disagreement, a recall hit) names the ontology element it concerns; the change ships as a versioned release with a changelog; the release regenerates every projection — skill bodies, rules JSON, knowledge-base projection, vocabularies, plan, grader map; the measurement that accepts it is the same set before and after. Weekly while a book is in translation. A release with no measurement is not a release.', meta: 'oe:ReviewFinding · CHANGELOG per context · scripts/check_ontology_release.py' },
];

